mapper.select:
SELECT t1.`id`, t1.`task_name`, t1.`task_time`, t1.`application_code`, t1.`application_name`, t1.`business_key`, t1.`business_type`, t1.`business_type_name`, t1.`business_status`, t1.`business_status_name`, t1.`business_principal`, t1.`status`, t1.`url`, t1.`task_del_state` FROM `work_task` t1 INNER JOIN `work_person` t2 on t1.`id` = t2.`work_task_id`
t2.`user_id` = #{userId} and t1.`status` = 'TODO' and t1.`task_del_state` = 0
and t1.`task_name` like concat('%',#{param.keyword},'%')
and t1.`business_type` in
#{businessType}
and t1.`task_time` >= #{param.period.begin}
and t1.`task_time` <= #{param.period.end}
order by t1.`task_time` DESC

SELECT t1.`id`, t1.`task_name`, t1.`task_time`, t1.`application_code`, t1.`application_name`, t1.`business_key`, t1.`business_type`, t1.`business_type_name`, t1.`business_status`, t1.`business_status_name`, t1.`next_business_status`, t1.`next_business_status_name`, t1.`business_principal`, t1.`handler_time`, t1.`status`, t1.`url`, t1.`task_del_state` FROM `work_task` t1 INNER JOIN `work_person` t2 on t1.`id` = t2.`work_task_id`
t2.`user_id` = #{userId} and t1.`status` = 'DONE' and t2.`status` = 'DONE' and t1.`task_del_state` = 0
and t1.`task_name` like concat('%',#{param.keyword},'%')
and t1.`business_type` in
#{businessType}
and t1.`task_time` >= #{param.period.begin}
and t1.`task_time` <= #{param.period.end}
order by t1.`task_time` desc

SELECT count(t1.`id`) as total FROM `work_task` t1
t1.`status` = 'TODO' and t1.`task_del_state` = 0
and t1.`task_time` >= #{period.begin}
and t1.`task_time` <= #{period.end}

SELECT t1.`business_type`, t1.`business_type_name`, count(t1.`id`) as total FROM `work_task` t1
t1.`status` = 'TODO' and t1.`task_del_state` = 0
and t1.`task_time` >= #{period.begin}
and t1.`task_time` <= #{period.end}
group by t1.`business_type`

SELECT DATE_FORMAT(t1.`task_time`,'%Y-%m-%d') as period, COUNT(t1.`id`) as total FROM `work_task` t1 INNER JOIN `work_person` t2 on t1.`id` = t2.`work_task_id`
t2.`user_id` = #{userId} and ((t1.`status` = 'TODO' and t1.`task_del_state` = 0) or (t1.`status` = 'DONE' and t2.`status` = 'TODO'))
and t1.`task_time` >= #{period.begin}
and t1.`task_time` <= #{period.end}
GROUP BY DATE_FORMAT(t1.`task_time`,'%Y-%m-%d')

SELECT
count(DISTINCT t1.`id`) AS number,
t3.work_tag_code as type
FROM
`work_task` t1
INNER JOIN `work_person` t2 ON t2.`work_task_id` = t1.`id`
INNER JOIN work_tag_refer_business_type t3 ON t3.business_type = t1.business_type

    t1.`task_del_state` = 0

        and t2.`status` = #{status}


        and t1.`status` = #{status}


        and t3.work_tag_code = #{param.type}


        and t1.`task_time` >= #{param.period.begin}


        and t1.`task_time` <= #{param.period.end}


        and t1.`business_type` in

            #{businessType}



        and t2.`user_id` in

            #{userId}



GROUP BY
t3.work_tag_code

SELECT `scope`.`group_id` AS `groupId`, COUNT(DISTINCT `task`.`id`) AS `number`, COUNT(DISTINCT CASE WHEN `person`.`status` = 'DONE' THEN `task`.`id` END) AS `doneNumber`, `tag_ref`.`work_tag_code` AS `type` FROM (
SELECT #{groupId} AS `group_id`, #{userId} AS `user_id`
) `scope` INNER JOIN `work_person` `person` ON `person`.`user_id` = `scope`.`user_id` INNER JOIN `work_task` `task` ON `task`.`id` = `person`.`work_task_id` INNER JOIN `work_tag_refer_business_type` `tag_ref` ON `tag_ref`.`business_type` = `task`.`business_type`
`task`.`task_del_state` = 0
AND `tag_ref`.`work_tag_code` = #{param.type}
AND `task`.`task_time` >= #{param.period.begin}
AND `task`.`task_time` <= #{param.period.end}
AND `task`.`business_type` IN
#{businessType}
GROUP BY `scope`.`group_id`, `tag_ref`.`work_tag_code`

SELECT t1.`id`, t1.`task_name`, t1.`task_time`, t1.`application_code`, t1.`application_name`, t1.`business_key`, t1.`business_type`, t1.`business_type_name`, t1.`business_status`, t1.`business_status_name`, t1.`business_principal`, t1.`handler_time`, t2.`status`, t1.`url`, t1.`task_del_state` FROM `work_task` t1 INNER JOIN `work_person` t2 on t1.`id` = t2.`work_task_id`
t1.`task_del_state` = 0
and t2.`status` = #{param.taskStatus}
and t1.`status` = #{param.taskStatus}
and t1.`business_status_name` = #{param.status}
and t1.`create_by` = #{param.createBy}
and t1.`task_name` like concat('%',#{param.keyword},'%')
and t1.`business_type` in
#{businessType}
and t1.`task_time` >= #{param.period.begin}
and t1.`task_time` <= #{param.period.end}
and t2.`user_id` in
#{userId}
GROUP BY t1.`id` order by t1.`task_time` desc

SELECT hr.`id`, hr.`record_name` AS recordName, hr.`task_num` AS taskNum, hr.`shift_over_time` AS shiftOverTime, hr.`shift_over_user` AS shiftOverUserId, hr.`take_over_user` AS takeOverUserId, hr.`take_over_time` AS takeOverTime, hr.`status` FROM `handover_record` hr
hr.`status` = 'WAIT_HANDOVER'
AND DATE_ADD(hr.`create_time`, INTERVAL IFNULL(#{value}, 0) MINUTE) >= #{period.begin}
AND DATE_ADD(hr.`create_time`, INTERVAL IFNULL(#{value}, 0) MINUTE) <= #{period.end}
